body.content:
body.gensen-product-page,
body.gensen-product-page #MainContent { background: #222222; }
.gensen-main-product {
  --color-foreground: 255, 255, 255;
  --color-background: 34, 34, 34;
  --color-button: 255, 105, 0;
  --color-button-text: 0, 0, 0;
  --color-secondary-button-text: 255, 105, 0;
  --color-link: 255, 105, 0;
  --buttons-radius: 40px;
  padding: 0;
  background: #222;
}
.gensen-main-product > product-component > .page-width { max-width: 1200px; padding: 80px 40px 100px; }
.gensen-main-product .product { display: grid; grid-template-columns: minmax(0, 640fr) minmax(0, 400fr); gap: 100px 80px; }
.gensen-main-product .product > .grid__item { width: 100%; max-width: none; min-width: 0; }
.gensen-main-product .product__media-wrapper { grid-column: 1; grid-row: 1; }
.gensen-main-product .product .product__info-wrapper { grid-column: 2; grid-row: 1 / span 2; padding: 0; }
.gensen-main-product .product__info-container { max-width: none; }
.gensen-main-product .product__info-container.product__column-sticky { top: 30px; }
.gensen-main-product media-gallery.product__column-sticky { position: static; }
.gensen-main-product .product__title { margin: 0 0 10px; }
.gensen-main-product .product__title h1 { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 13px; font: 600 50px/1.2 'Montserrat', 'Noto Sans JP', sans-serif; overflow-wrap: anywhere; }
.gensen-main-product .product__title .gensen-product-label { font: 700 30px/1.2 'Noto Sans JP', sans-serif; }
.gensen-main-product .product__info-container > div { margin-block: 24px; }
.gensen-main-product .product__title + div { margin-top: 8px; }
.gensen-main-product .product__info-container > .product__title { margin-top: 0; }
.gensen-main-product .price { color: #fff; }
.gensen-main-product .price--large { font-size: 28px; }
.gensen-main-product .gensen-badges { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); margin-top: 40px !important; }
.gensen-main-product .gensen-badges li { padding: 4px; font-size: 10px; white-space: normal; overflow-wrap: anywhere; }
.gensen-main-product .product-form { margin: 24px 0 0; }
.gensen-main-product .product-form__submit { width: 260px; max-width: 100%; border-radius: 40px; min-height: 60px; font-size: 16px; }
.gensen-main-product .product-form__submit::after, .gensen-main-product .product-form__submit::before { border-radius: 40px; }
.gensen-main-product .product-form__submit { transition: background-color .22s ease, color .22s ease, border-color .22s ease; }
.gensen-main-product .product-form__submit::after { box-shadow: 0 0 0 1px #ff6900; }
.gensen-main-product .product-form__submit:not(:disabled):hover,
.gensen-main-product .product-form__submit:not(:disabled):focus-visible { background: #222; color: #ff6900; }
.gensen-main-product .product-form__submit:not(:disabled):hover::after { box-shadow: 0 0 0 1px #ff6900; }
.gensen-main-product .product-form__submit:disabled { cursor: not-allowed; }
.gensen-main-product .thumbnail { transition: border-color .22s ease, opacity .22s ease; }
.gensen-main-product .thumbnail:hover { opacity: .75; }
.gensen-main-product .gensen-faq__items { display: block; }
.gensen-main-product .gensen-faq__item summary { transition: color .22s ease, background-color .22s ease; }
.gensen-main-product .gensen-faq__item summary:hover,
.gensen-main-product .gensen-faq__item summary:focus-visible { color: #ff6900; }
.gensen-main-product .gensen-faq__item summary > span::after { transition: transform .26s ease; }
.gensen-main-product .gensen-faq-link { transition: color .22s ease; }
.gensen-main-product .gensen-button__hover-art { position: absolute; inset: 0; opacity: 0; transition: opacity .22s ease; }
.gensen-main-product a.gensen-faq-link:hover,
.gensen-main-product a.gensen-faq-link:focus-visible { color: #000 !important; filter: none; }
.gensen-main-product a.gensen-faq-link:hover .gensen-button__hover-art,
.gensen-main-product a.gensen-faq-link:focus-visible .gensen-button__hover-art { opacity: 1; }
.gensen-main-product .gensen-related__card { transition: background-color .22s ease, color .22s ease; }
.gensen-main-product .gensen-related__card:hover { background: #222; }
.gensen-main-product .product__media-list { margin: 0; }
.gensen-main-product .product__media-item { background: #000; }
.gensen-main-product .product-media-container.media-type-image { --aspect-ratio: 1; border: 0; background: #000; max-width: 100%; }
.gensen-main-product .media-type-image .product__media img { object-fit: contain; padding: 13.125% 2% 2%; }
.gensen-main-product .thumbnail img { object-fit: contain; padding: 13.125% 2% 2%; }
.gensen-main-product .thumbnail-list { margin-top: 24px; padding: 0; }
.gensen-main-product .product__media-wrapper .thumbnail-list.slider { padding: 0; gap: 26.6667px; }
.gensen-main-product .product__media-wrapper .thumbnail-list .thumbnail-list__item { width: calc((100% - 80px) / 4); flex: 0 0 calc((100% - 80px) / 4); }
.gensen-main-product .thumbnail { background: #000; }
.gensen-main-product .thumbnail[aria-current='true'] { border: 2px solid #ff6900; box-shadow: none; }
.gensen-main-product .gensen-content { grid-column: 1; grid-row: 2; margin: 0; min-width: 0; }
.gensen-main-product .gensen-story__heading h2 { min-width: 0; overflow-wrap: anywhere; }
.gensen-main-product .gensen-faq__item summary,
.gensen-main-product .gensen-faq__answer { overflow-wrap: anywhere; }
.gensen-main-product .gensen-related__card { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.gensen-main-product .gensen-related__text { min-width: 0; overflow-wrap: anywhere; }
.gensen-main-product .gensen-catchphrase,
.gensen-main-product .gensen-related__catch { white-space: pre-line; overflow-wrap: anywhere; }
.gensen-main-product .gensen-catchphrase { margin-bottom: 24px; font-size: 30px; line-height: 1.4; }
.gensen-main-product .gensen-product-description p + p { margin-top: 1em; }
.gensen-main-product .gensen-related__text h3 .gensen-product-label { display: block; margin-top: 10px; font: 500 18px/1.4 'Noto Sans JP', sans-serif; }
.gensen-main-product .gensen-related__catch { display: none; }
.gensen-main-product .gensen-product-description { line-height: 1.8; overflow-wrap: anywhere; }
.gensen-main-product .gensen-related__image img { object-fit: contain; }
.gensen-main-product .gensen-footer { margin: 0; }
.gensen-main-product .product__tax { margin-top: 8px; }
/* Subscription widget v2: scope to the app root, not generated styled-component classes. */
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] { color: #fff; font-family: 'Noto Sans JP', sans-serif; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] > div { margin: 0; color: inherit; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] > div > div { padding: 20px; border: 0; border-radius: 0; background: #000; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] > div > div > p { margin: 0 0 16px; color: #ff6900; font-size: 14px; font-weight: 700; line-height: 1.6; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] div:has(> input[name='planOption']) { display: grid; gap: 12px; border: 0; background: transparent; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] {
  display: block; position: absolute; width: 1px; height: 1px; margin: 0; padding: 0;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;
}
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 12px;
  position: relative; min-width: 0; margin: 0; padding: 16px 12px 16px 44px;
  border: 1px solid #666; border-radius: 0; background: #222; color: #fff; cursor: pointer;
  transition: background-color .22s ease, border-color .22s ease;
}
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label > div { min-width: 0; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label p { color: inherit; line-height: 1.6; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label > div:first-child > p:first-child { margin: 0 0 6px; font-size: 14px; font-weight: 700; overflow-wrap: anywhere; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label > div:first-child > p + p { margin: 0; color: #ccc; font-size: 12px; overflow-wrap: anywhere; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label > div:last-child > p { margin: 0; font-size: 18px; font-weight: 600; white-space: nowrap; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label::before,
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label::after {
  content: ''; position: absolute; top: 50%; border-radius: 50%; transform: translateY(-50%);
  box-sizing: border-box; transition: border-color .22s ease, background-color .22s ease, opacity .22s ease;
}
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label::before { left: 16px; width: 18px; height: 18px; border: 1px solid #aaa; background: transparent; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label::after { left: 21px; width: 8px; height: 8px; border: 0; background: #ff6900; opacity: 0; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label:hover { border-color: #ff6900; background: #2c2c2c; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption']:checked + label { border-color: #ff6900; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption']:checked + label::before { border-color: #ff6900; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption']:checked + label::after { opacity: 1; }
.gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption']:focus-visible + label { outline: 1px solid #ff6900; outline-offset: 3px; }
@media (max-width: 749px) {
  .gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] > div > div { padding: 16px; }
  .gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label { column-gap: 8px; }
  .gensen-main-product .product__info-container .huckleberry-subscription-widget-container[data-widget-version='2'] input[name='planOption'] + label > div:last-child > p { font-size: 16px; }
}
@media (min-width: 990px) and (max-width: 1250px) {
  .gensen-main-product .product { grid-template-columns: minmax(0, 1fr) 350px; column-gap: 40px; }
}
@media (max-width: 989px) {
  .gensen-main-product > product-component > .page-width { max-width: 690px; padding: 20px 25px 60px; }
  .gensen-main-product .product { display: flex; flex-direction: column; gap: 0; }
  .gensen-main-product .product__media-wrapper { order: 0; }
  .gensen-main-product .product__info-wrapper { order: 1; margin-top: 40px; }
  .gensen-main-product .product-form__submit { display: flex; width: 225px; margin-inline: auto; }
  .gensen-main-product .gensen-content { order: 2; margin-top: 80px; }
  .gensen-main-product .product__info-container.product__column-sticky { position: static; }
  .gensen-main-product .product__title h1 { font-size: 30px; }
  .gensen-main-product .product__title .gensen-product-label { font-size: 18px; }
  .gensen-main-product .gensen-subtitle { font-size: 14px; }
  .gensen-main-product .product__info-container > div { margin-block: 20px; }
  .gensen-main-product .product__media-list { width: 100%; margin: 0; scroll-padding-left: 0; }
  .gensen-main-product .product .product__media-list .product__media-item { width: 100%; margin-left: 0; padding: 0; }
  .gensen-main-product .product__media-list::after { display: none; }
  .gensen-main-product .product .product__media-wrapper .slider-mobile-gutter { margin: 0; }
  .gensen-main-product .product__media-wrapper .thumbnail-list.slider { gap: 15px; margin-top: 14px; }
  .gensen-main-product .product__media-wrapper .thumbnail-list .thumbnail-list__item { width: calc((100% - 45px) / 4); flex-basis: calc((100% - 45px) / 4); }
  .gensen-main-product .gensen-story__image { height: 250px; }
  .gensen-main-product .gensen-point > span { color: #fff; }
  .gensen-main-product .gensen-badges { margin-top: 20px !important; }
  .gensen-main-product .gensen-related__card { grid-template-columns: minmax(0, 1fr); }
  .gensen-main-product .gensen-related__text { display: block; }
  .gensen-main-product .gensen-related__text h3 { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 15px; }
  .gensen-main-product .gensen-related__text h3 .gensen-product-label { margin: 0; }
  .gensen-main-product .gensen-related__catch { display: block; color: #fff; font-size: 18px; margin-top: 4px !important; }
  .gensen-main-product .gensen-related__text { background: #222; }
  .gensen-main-product .gensen-related__image { background: #000; }
  .gensen-main-product .gensen-catchphrase { font-size: 24px; }
}
@media (prefers-reduced-motion: reduce) {
  .gensen-main-product *, .gensen-main-product *::before, .gensen-main-product *::after { transition: none !important; }
}
